export type DesignModeId = (typeof designModeIds)[number];
export type DesignModeDefinition = {
    id: DesignModeId;
    name: string;
    group: string;
    kind: "기본" | "시각 스타일" | "디자인 시스템" | "레이아웃" | "테마" | "인터페이스 방식";
